-- Dream Kitchen menu seed data for Cloudflare D1. Generated by: node scripts/d1-seed-menu.mjs
-- Safe to run again: it never touches prices or custom photos set in admin.
ON CONFLICT (id) DO UPDATE SET slug = excluded.slug, category = excluded.category, name_en = excluded.name_en, name_kn = excluded.name_kn, options = excluded.options, courier_tier = excluded.courier_tier, sort = excluded.sort, image = excluded.image;
